1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8" />
5	  <title>Rollout — design canvas</title>
6	  <link rel="stylesheet" href="styles.css" />
7	  <style>
8	    body { margin: 0; }
9	    .ab-wrap { width: 100%; height: 100%; overflow: hidden; }
10	    .ab-wrap .app { min-height: 100%; }
11	
12	    /* View frame artboard */
13	    .view-artboard {
14	      width: 100%; height: 100%;
15	      background: #0d0d0e;
16	      display: grid; place-items: center;
17	      position: relative;
18	    }
19	    .view-artboard iframe {
20	      width: 100%; height: 100%;
21	      border: 0; background: #fff;
22	    }
23	
24	    /* Spec note for design tokens */
25	    .spec {
26	      width: 100%; height: 100%;
27	      padding: 24px;
28	      background: #FFFFFF;
29	      border: 1px solid #E4E4E7;
30	      border-radius: 4px;
31	      display: grid;
32	      gap: 18px;
33	      align-content: start;
34	      font-family: 'IBM Plex Sans', sans-serif;
35	      overflow-y: auto;
36	    }
37	    .spec h3 {
38	      font-weight: 600;
39	      font-size: 14px;
40	      margin: 0 0 4px;
41	      color: #18181B;
42	    }
43	    .spec h3 .sub {
44	      display: block;
45	      font-weight: 400;
46	      font-size: 11px;
47	      color: #71717A;
48	      margin-top: 2px;
49	      font-family: 'IBM Plex Mono', monospace;
50	    }
51	    .spec .label {
52	      font-family: 'IBM Plex Mono', monospace;
53	      font-size: 10px;
54	      letter-spacing: 0.02em;
55	      color: #71717A;
56	      text-transform: uppercase;
57	      margin-bottom: 6px;
58	    }
59	    .spec .grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; }
60	    .spec .grid3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 4px; }
61	    .spec .sw {
62	      height: 36px;
63	      border-radius: 3px;
64	      border: 1px solid rgba(0,0,0,0.05);
65	      display: flex;
66	      align-items: flex-end;
67	      justify-content: flex-start;
68	      padding: 4px 6px;
69	      font-family: 'IBM Plex Mono', monospace;
70	      font-size: 9px;
71	      color: rgba(0,0,0,0.55);
72	    }
73	    .spec .sw.dark { color: rgba(255,255,255,0.75); }
74	    .spec p, .spec li {
75	      font-size: 12px;
76	      color: #3F3F46;
77	      line-height: 1.5;
78	      margin: 0;
79	    }
80	    .spec ul { padding-left: 16px; margin: 0; display: grid; gap: 4px; }
81	    .spec .type-row {
82	      display: flex; align-items: baseline; gap: 10px;
83	      padding: 4px 0;
84	      border-bottom: 1px dashed #E4E4E7;
85	    }
86	    .spec .type-row:last-child { border-bottom: none; }
87	    .spec .type-row .meta {
88	      font-family: 'IBM Plex Mono', monospace;
89	      font-size: 10px;
90	      color: #71717A;
91	      width: 80px;
92	      flex-shrink: 0;
93	    }
94	    .spec .type-row .sample { color: #18181B; }
95	    .spec .type-row .sample.mono { font-family: 'IBM Plex Mono', monospace; }
96	    .spec .kvs {
97	      display: grid;
98	      grid-template-columns: 110px 1fr;
99	      gap: 4px 12px;
100	      font-size: 11px;
101	    }
102	    .spec .kvs dt {
103	      font-family: 'IBM Plex Mono', monospace;
104	      color: #71717A;
105	    }
106	    .spec .kvs dd {
107	      margin: 0;
108	      color: #18181B;
109	      font-family: 'IBM Plex Mono', monospace;
110	    }
111	  </style>
112	</head>
113	<body>
114	  <div id="root"></div>
115	
116	  <script src="https://unpkg.com/react@18.3.1/umd/react.development.js" integrity="sha384-hD6/rw4ppMLGNu3tX5cjIb+uRZ7UkRJ6BPkLpg4hAu/6onKUg4lLsHAs9EBPT82L" crossorigin="anonymous"></script>
117	  <script src="https://unpkg.com/react-dom@18.3.1/umd/react-dom.development.js" integrity="sha384-u6aeetuaXnQ38mYT8rp6sbXaQe3NL9t+IBXmnYxwkUI2Hw4bsp2Wvmx4yRQF1uAm" crossorigin="anonymous"></script>
118	  <script src="https://unpkg.com/@babel/standalone@7.29.0/babel.min.js" integrity="sha384-m08KidiNqLdpJqLq95G/LEi8Qvjl/xUYll3QILypMoQ65QorJ9Lvtp2RXYGBFj1y" crossorigin="anonymous"></script>
119	
120	  <script type="text/babel" src="design-canvas.jsx"></script>
121	  <script type="text/babel" src="data.jsx"></script>
122	  <script type="text/babel" src="ui.jsx"></script>
123	  <script type="text/babel" src="dashboard.jsx"></script>
124	  <script type="text/babel" src="frozen.jsx"></script>
125	
126	  <script type="text/babel">
127	    const user = window.CURRENT_USER;
128	    const items = window.MOCK_PRESENTATIONS;
129	    const empty = [];
130	
131	    const ABw = 1100;
132	    const ABh = 820;
133	
134	    function App() {
135	      return (
136	        <DesignCanvas>
137	          <DCSection
138	            id="system"
139	            title="rollout"
140	            subtitle="Internal HTML-presentation sharing tool · utilitarian · single screen, two modalities"
141	          >
142	            <DCArtboard id="tokens" label="design tokens" width={420} height={ABh}>
143	              <div className="spec">
144	                <div>
145	                  <h3>tokens<span className="sub">rollout/design-system</span></h3>
146	                </div>
147	
148	                <div>
149	                  <div className="label">surface</div>
150	                  <div className="grid3">
151	                    <div className="sw" style={{ background: '#FAFAFA' }}>--bg</div>
152	                    <div className="sw" style={{ background: '#F4F4F5' }}>--bg-2</div>
153	                    <div className="sw" style={{ background: '#FFFFFF' }}>--surface</div>
154	                  </div>
155	                </div>
156	
157	                <div>
158	                  <div className="label">ink</div>
159	                  <div className="grid3">
160	                    <div className="sw dark" style={{ background: '#18181B' }}>--ink</div>
161	                    <div className="sw dark" style={{ background: '#3F3F46' }}>--ink-2</div>
162	                    <div className="sw" style={{ background: '#71717A', color: 'rgba(255,255,255,0.85)' }}>--muted</div>
163	                  </div>
164	                </div>
165	
166	                <div>
167	                  <div className="label">accent · status</div>
168	                  <div className="grid3">
169	                    <div className="sw dark" style={{ background: '#2563EB' }}>--accent</div>
170	                    <div className="sw dark" style={{ background: '#16A34A' }}>--success</div>
171	                    <div className="sw dark" style={{ background: '#DC2626' }}>--danger</div>
172	                  </div>
173	                </div>
174	
175	                <div>
176	                  <div className="label">type</div>
177	                  <div className="type-row">
178	                    <span className="meta">heading/600</span>
179	                    <span className="sample" style={{ fontWeight: 600, fontSize: 18 }}>Presentations</span>
180	                  </div>
181	                  <div className="type-row">
182	                    <span className="meta">body/400</span>
183	                    <span className="sample" style={{ fontSize: 13 }}>Drop .html file or click to browse</span>
184	                  </div>
185	                  <div className="type-row">
186	                    <span className="meta">mono/400</span>
187	                    <span className="sample mono" style={{ fontSize: 12 }}>/jdoe/q3-platform-review</span>
188	                  </div>
189	                  <div className="type-row">
190	                    <span className="meta">label/500</span>
191	                    <span className="sample" style={{ fontSize: 11, color: '#71717A' }}>shared · views · last viewed</span>
192	                  </div>
193	                </div>
194	
195	                <div>
196	                  <div className="label">geometry</div>
197	                  <dl className="kvs">
198	                    <dt>radius</dt><dd>3px / 4px</dd>
199	                    <dt>row-height</dt><dd>36px</dd>
200	                    <dt>btn-height</dt><dd>28px</dd>
201	                    <dt>shell-pad</dt><dd>24px / 32px</dd>
202	                    <dt>max-width</dt><dd>960px</dd>
203	                  </dl>
204	                </div>
205	
206	                <div>
207	                  <div className="label">principles</div>
208	                  <ul>
209	                    <li>SSO assumed · no auth UI</li>
210	                    <li>One screen, two states</li>
211	                    <li>Slug auto-derives from filename</li>
212	                    <li>URL auto-copies on share</li>
213	                    <li>Viewer is full-bleed, no chrome</li>
214	                  </ul>
215	                </div>
216	              </div>
217	            </DCArtboard>
218	
219	            <DCArtboard id="dash-default" label="01 · dashboard (default)" width={ABw} height={ABh}>
220	              <div className="ab-wrap">
221	                <FrozenDashboard user={user} items={items} sharePanelState={null} />
222	              </div>
223	            </DCArtboard>
224	
225	            <DCArtboard id="dash-share-empty" label="02 · share panel open (empty)" width={ABw} height={ABh}>
226	              <div className="ab-wrap">
227	                <FrozenDashboard user={user} items={items} sharePanelState="empty" hideShareCta />
228	              </div>
229	            </DCArtboard>
230	
231	            <DCArtboard id="dash-share-filled" label="03 · share panel (filled, slug live)" width={ABw} height={ABh}>
232	              <div className="ab-wrap">
233	                <FrozenDashboard user={user} items={items} sharePanelState="filled" hideShareCta />
234	              </div>
235	            </DCArtboard>
236	
237	            <DCArtboard id="dash-success" label="04 · success (url copied)" width={ABw} height={ABh}>
238	              <div className="ab-wrap">
239	                <FrozenDashboard
240	                  user={user}
241	                  items={[{ id: 'new', title: 'design review', slug: 'design-review-may-04', uploaded: 'just now', lastViewed: '—', views: 0 }, ...items]}
242	                  sharePanelState="success"
243	                  hideShareCta
244	                />
245	              </div>
246	            </DCArtboard>
247	
248	            <DCArtboard id="empty" label="05 · empty (first-time user)" width={ABw} height={ABh}>
249	              <div className="ab-wrap">
250	                <FrozenDashboard user={user} items={empty} sharePanelState={null} />
251	              </div>
252	            </DCArtboard>
253	
254	            <DCArtboard id="view" label="06 · view page (full-bleed, no chrome)" width={ABw} height={ABh}>
255	              <div className="view-artboard">
256	                <iframe src="sample-deck.html" title="shared deck"></iframe>
257	              </div>
258	            </DCArtboard>
259	
260	            <DCArtboard id="prototype-link" label="live prototype" width={420} height={ABh}>
261	              <div className="spec" style={{ background: '#18181B', borderColor: '#18181B' }}>
262	                <div>
263	                  <h3 style={{ color: '#FAFAFA' }}>
264	                    live prototype
265	                    <span className="sub" style={{ color: '#71717A' }}>Dashboard.html</span>
266	                  </h3>
267	                </div>
268	                <p style={{ color: '#A1A1AA' }}>
269	                  Variations on this canvas are frozen renders. The clickable version with working drag-drop, slug derivation, copy-to-clipboard, search filter, rename, and delete is in <code style={{ fontFamily: 'IBM Plex Mono, monospace', color: '#60A5FA' }}>Dashboard.html</code>.
270	                </p>
271	                <div>
272	                  <div className="label" style={{ color: '#71717A' }}>flow</div>
273	                  <ul style={{ color: '#A1A1AA' }}>
274	                    <li>Click "Share new" → panel expands</li>
275	                    <li>Drop file → name + slug auto-fill</li>
276	                    <li>Click Share → URL copied automatically</li>
277	                    <li>Hover row → copy / open / more</li>
278	                    <li>Filter via toolbar search</li>
279	                  </ul>
280	                </div>
281	                <a href="Dashboard.html" target="_blank"
282	                   style={{
283	                     display: 'inline-flex', alignItems: 'center', gap: 6,
284	                     padding: '8px 14px', borderRadius: 3,
285	                     background: '#2563EB', color: '#fff',
286	                     fontFamily: 'IBM Plex Sans', fontSize: 12, fontWeight: 500,
287	                     textDecoration: 'none', justifySelf: 'start',
288	                   }}>
289	                  Open Dashboard.html →
290	                </a>
291	              </div>
292	            </DCArtboard>
293	          </DCSection>
294	        </DesignCanvas>
295	      );
296	    }
297	
298	    const root = ReactDOM.createRoot(document.getElementById('root'));
299	    root.render(<App />);
300	  </script>
301	</body>
302	</html>
303

1	/* Rollout — utilitarian internal tool */
2	@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');
3	
4	:root {
5	  --bg: #FAFAFA;
6	  --bg-2: #F4F4F5;
7	  --surface: #FFFFFF;
8	  --ink: #18181B;
9	  --ink-2: #3F3F46;
10	  --muted: #71717A;
11	  --muted-2: #A1A1AA;
12	  --hairline: #E4E4E7;
13	  --hairline-strong: #D4D4D8;
14	  --accent: #2563EB;
15	  --accent-soft: #DBEAFE;
16	  --accent-ink: #1E40AF;
17	  --success: #16A34A;
18	  --success-soft: #DCFCE7;
19	  --danger: #DC2626;
20	  --danger-soft: #FEE2E2;
21	  --warn-soft: #FEF3C7;
22	
23	  --font-sans: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
24	  --font-mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, monospace;
25	
26	  --radius: 4px;
27	  --radius-sm: 3px;
28	}
29	
30	* { box-sizing: border-box; }
31	
32	html, body {
33	  margin: 0; padding: 0;
34	  background: var(--bg);
35	  color: var(--ink);
36	  font-family: var(--font-sans);
37	  font-size: 13px;
38	  line-height: 1.45;
39	  -webkit-font-smoothing: antialiased;
40	}
41	
42	button {
43	  font-family: inherit; font-size: inherit; color: inherit;
44	  background: none; border: none; padding: 0; cursor: pointer;
45	}
46	input, textarea {
47	  font-family: inherit; font-size: inherit; color: inherit;
48	  background: none; border: none; outline: none; padding: 0;
49	}
50	
51	/* ——— App shell ——— */
52	.app {
53	  width: 100%;
54	  min-height: 100%;
55	  background: var(--bg);
56	}
57	
58	.shell {
59	  max-width: 960px;
60	  margin: 0 auto;
61	  padding: 24px 32px 64px;
62	}
63	
64	/* ——— Top bar ——— */
65	.topbar {
66	  display: flex;
67	  align-items: center;
68	  justify-content: space-between;
69	  height: 44px;
70	  border-bottom: 1px solid var(--hairline);
71	  margin-bottom: 24px;
72	}
73	.wordmark {
74	  display: flex; align-items: center; gap: 10px;
75	  font-family: var(--font-mono);
76	  font-size: 13px;
77	  font-weight: 500;
78	  letter-spacing: -0.01em;
79	  color: var(--ink);
80	}
81	.wordmark .logo {
82	  width: 18px; height: 18px;
83	  border-radius: 3px;
84	  background: var(--ink);
85	  color: #fff;
86	  display: grid; place-items: center;
87	  font-family: var(--font-mono);
88	  font-size: 11px;
89	  font-weight: 600;
90	}
91	.wordmark .env {
92	  margin-left: 4px;
93	  font-size: 11px;
94	  color: var(--muted);
95	  font-weight: 400;
96	  padding: 2px 6px;
97	  border: 1px solid var(--hairline);
98	  border-radius: 2px;
99	}
100	.who {
101	  display: flex; align-items: center; gap: 10px;
102	  font-size: 12px; color: var(--ink-2);
103	}
104	.who .avatar {
105	  width: 22px; height: 22px;
106	  border-radius: 50%;
107	  background: var(--bg-2);
108	  color: var(--ink-2);
109	  font-size: 10px;
110	  font-weight: 600;
111	  display: grid; place-items: center;
112	  border: 1px solid var(--hairline);
113	}
114	
115	/* ——— Page heading ——— */
116	.heading {
117	  display: flex;
118	  align-items: center;
119	  justify-content: space-between;
120	  padding: 4px 0 16px;
121	}
122	.heading h1 {
123	  font-family: var(--font-sans);
124	  font-weight: 600;
125	  font-size: 18px;
126	  line-height: 1.2;
127	  letter-spacing: -0.005em;
128	  margin: 0;
129	}
130	.heading .sub {
131	  color: var(--muted);
132	  font-size: 12px;
133	  margin-top: 2px;
134	}
135	
136	/* ——— Buttons ——— */
137	.btn {
138	  display: inline-flex;
139	  align-items: center;
140	  gap: 6px;
141	  height: 28px;
142	  padding: 0 12px;
143	  border: 1px solid var(--ink);
144	  background: var(--ink);
145	  color: #fff;
146	  border-radius: var(--radius-sm);
147	  font-size: 12px;
148	  font-weight: 500;
149	  letter-spacing: 0;
150	  transition: background 100ms ease;
151	}
152	.btn:hover { background: #000; border-color: #000; }
153	.btn:active { transform: translateY(0.5px); }
154	
155	.btn-ghost {
156	  background: var(--surface);
157	  border: 1px solid var(--hairline-strong);
158	  color: var(--ink-2);
159	}
160	.btn-ghost:hover { background: var(--bg-2); color: var(--ink); }
161	
162	.btn-accent {
163	  background: var(--accent);
164	  border-color: var(--accent);
165	  color: #fff;
166	}
167	.btn-accent:hover { background: var(--accent-ink); border-color: var(--accent-ink); }
168	
169	.btn[disabled], .btn:disabled {
170	  opacity: 0.45; cursor: not-allowed;
171	}
172	
173	.kbd {
174	  font-family: var(--font-mono);
175	  font-size: 10px;
176	  padding: 1px 4px;
177	  border: 1px solid var(--hairline-strong);
178	  border-bottom-width: 2px;
179	  border-radius: 2px;
180	  color: var(--muted);
181	  background: var(--surface);
182	}
183	
184	/* ——— Toolbar above list ——— */
185	.toolbar {
186	  display: flex;
187	  align-items: center;
188	  justify-content: space-between;
189	  gap: 12px;
190	  padding: 8px 0;
191	  border-top: 1px solid var(--hairline);
192	  border-bottom: 1px solid var(--hairline);
193	}
194	.search {
195	  display: flex; align-items: center; gap: 8px;
196	  flex: 1;
197	  height: 28px;
198	  padding: 0 10px;
199	  border: 1px solid var(--hairline);
200	  border-radius: var(--radius-sm);
201	  background: var(--surface);
202	  color: var(--muted);
203	  font-size: 12px;
204	  max-width: 320px;
205	}
206	.search input {
207	  flex: 1;
208	  color: var(--ink);
209	  background: transparent;
210	}
211	.search input::placeholder { color: var(--muted-2); }
212	.toolbar .stats { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
213	
214	/* ——— Share panel (inline expanding) ——— */
215	.share-panel {
216	  background: var(--surface);
217	  border: 1px solid var(--hairline);
218	  border-radius: var(--radius);
219	  margin: 12px 0;
220	}
221	.share-panel-head {
222	  display: flex; align-items: center; justify-content: space-between;
223	  padding: 10px 14px;
224	  border-bottom: 1px solid var(--hairline);
225	}
226	.share-panel-head .t {
227	  font-size: 12px; font-weight: 600; color: var(--ink);
228	  display: flex; align-items: center; gap: 8px;
229	}
230	.share-panel-head .t .badge {
231	  font-family: var(--font-mono);
232	  font-size: 10px;
233	  padding: 1px 6px;
234	  background: var(--bg-2);
235	  border-radius: 2px;
236	  color: var(--muted);
237	  font-weight: 400;
238	}
239	.share-panel-head .x {
240	  width: 22px; height: 22px;
241	  display: grid; place-items: center;
242	  color: var(--muted);
243	  border-radius: 3px;
244	}
245	.share-panel-head .x:hover { background: var(--bg-2); color: var(--ink); }
246	
247	.share-panel-inner {
248	  padding: 14px;
249	  display: grid;
250	  gap: 0;
251	}
252	
253	.dropzone {
254	  border: 1px dashed var(--hairline-strong);
255	  border-radius: var(--radius-sm);
256	  padding: 14px;
257	  display: flex;
258	  align-items: center;
259	  justify-content: space-between;
260	  gap: 12px;
261	  background: var(--bg);
262	  transition: border-color 100ms ease, background 100ms ease;
263	  cursor: pointer;
264	}
265	.dropzone:hover { border-color: var(--accent); }
266	.dropzone.active {
267	  border-color: var(--accent);
268	  background: var(--accent-soft);
269	}
270	.dropzone .dz-left {
271	  display: flex; align-items: center; gap: 10px;
272	}
273	.dropzone .dz-icon {
274	  width: 28px; height: 32px;
275	  border: 1px solid var(--hairline-strong);
276	  border-radius: 2px;
277	  background: #fff;
278	  position: relative;
279	  flex-shrink: 0;
280	  display: grid; place-items: center;
281	  font-family: var(--font-mono);
282	  font-size: 8px;
283	  color: var(--muted);
284	  letter-spacing: 0;
285	}
286	.dropzone.has-file .dz-icon {
287	  border-color: var(--accent);
288	  color: var(--accent);
289	}
290	.dz-title { font-size: 12px; font-weight: 500; color: var(--ink); }
291	.dz-meta  { font-size: 11px; color: var(--muted); margin-top: 1px; font-variant-numeric: tabular-nums; }
292	
293	.fields {
294	  display: grid;
295	  margin-top: 10px;
296	}
297	.field {
298	  display: grid;
299	  grid-template-columns: 84px 1fr;
300	  align-items: center;
301	  gap: 12px;
302	  padding: 9px 10px;
303	  border: 1px solid var(--hairline);
304	  border-bottom: none;
305	}
306	.field:first-child { border-top-left-radius: var(--radius-sm); border-top-right-radius: var(--radius-sm); }
307	.field:last-child { border-bottom: 1px solid var(--hairline); border-bottom-left-radius: var(--radius-sm); border-bottom-right-radius: var(--radius-sm); }
308	.field label {
309	  font-size: 11px;
310	  color: var(--muted);
311	  font-weight: 500;
312	}
313	.field .input {
314	  font-family: var(--font-sans);
315	  font-size: 13px;
316	  color: var(--ink);
317	  width: 100%;
318	}
319	.field .input.mono { font-family: var(--font-mono); font-size: 12px; }
320	.field .input::placeholder { color: var(--muted-2); }
321	
322	.field .preview {
323	  font-family: var(--font-mono);
324	  font-size: 12px;
325	  color: var(--muted);
326	}
327	.field .preview .slug {
328	  color: var(--ink);
329	  background: var(--accent-soft);
330	  padding: 1px 4px;
331	  border-radius: 2px;
332	}
333	
334	.share-actions {
335	  display: flex;
336	  align-items: center;
337	  justify-content: space-between;
338	  gap: 8px;
339	  padding-top: 12px;
340	}
341	.share-actions .hint { font-size: 11px; color: var(--muted); }
342	.share-actions .actions { display: flex; gap: 6px; }
343	
344	/* ——— Success card ——— */
345	.success {
346	  display: grid;
347	  gap: 12px;
348	}
349	.success .ok {
350	  display: flex; align-items: center; gap: 8px;
351	  font-size: 12px; color: var(--ink-2);
352	  padding: 8px 10px;
353	  background: var(--success-soft);
354	  border-radius: var(--radius-sm);
355	}
356	.success .ok .check {
357	  width: 14px; height: 14px;
358	  border-radius: 50%;
359	  background: var(--success);
360	  color: #fff;
361	  display: grid; place-items: center;
362	  font-size: 9px;
363	  flex-shrink: 0;
364	}
365	.url-pill {
366	  display: flex; align-items: stretch;
367	  border: 1px solid var(--hairline-strong);
368	  border-radius: var(--radius-sm);
369	  background: var(--surface);
370	  overflow: hidden;
371	}
372	.url-pill .url {
373	  font-family: var(--font-mono);
374	  font-size: 12px;
375	  color: var(--ink);
376	  flex: 1;
377	  overflow: hidden;
378	  text-overflow: ellipsis;
379	  white-space: nowrap;
380	  padding: 7px 10px;
381	  background: var(--bg);
382	}
383	.url-pill .url .em { color: var(--accent); }
384	.url-pill button {
385	  height: auto;
386	  padding: 0 12px;
387	  background: var(--ink);
388	  color: #fff;
389	  font-size: 12px;
390	  font-weight: 500;
391	  display: inline-flex; align-items: center; gap: 6px;
392	  border-left: 1px solid var(--ink);
393	}
394	.url-pill button:hover { background: #000; }
395	.url-pill button.copied {
396	  background: var(--success);
397	}
398	
399	/* ——— List ——— */
400	.list {
401	  background: var(--surface);
402	  border: 1px solid var(--hairline);
403	  border-top: none;
404	  border-radius: 0 0 var(--radius) var(--radius);
405	}
406	.list-head {
407	  display: grid;
408	  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.2fr) 92px 70px 90px 36px;
409	  gap: 16px;
410	  padding: 8px 12px;
411	  font-size: 11px;
412	  font-weight: 500;
413	  color: var(--muted);
414	  background: var(--bg-2);
415	  border-bottom: 1px solid var(--hairline);
416	}
417	.list-head > div {
418	  display: flex; align-items: center; gap: 4px;
419	}
420	.list-head .col-num { text-align: right; justify-content: flex-end; font-variant-numeric: tabular-nums; }
421	
422	.row {
423	  display: grid;
424	  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.2fr) 92px 70px 90px 36px;
425	  gap: 16px;
426	  align-items: center;
427	  padding: 9px 12px;
428	  border-bottom: 1px solid var(--hairline);
429	  position: relative;
430	  font-size: 13px;
431	}
432	.row:last-child { border-bottom: none; }
433	.row:hover { background: var(--bg); }
434	
435	.row .name .title {
436	  font-size: 13px;
437	  font-weight: 500;
438	  color: var(--ink);
439	  white-space: nowrap;
440	  overflow: hidden;
441	  text-overflow: ellipsis;
442	}
443	.row .slug-col {
444	  font-family: var(--font-mono);
445	  font-size: 11.5px;
446	  color: var(--muted);
447	  white-space: nowrap;
448	  overflow: hidden;
449	  text-overflow: ellipsis;
450	}
451	.row .col {
452	  font-size: 12px;
453	  color: var(--ink-2);
454	  font-variant-numeric: tabular-nums;
455	  white-space: nowrap;
456	}
457	.row .col.muted { color: var(--muted); }
458	.row .col.num { text-align: right; }
459	
460	.row-actions {
461	  display: flex;
462	  align-items: center;
463	  gap: 0;
464	  position: relative;
465	  justify-self: end;
466	}
467	.row-actions button {
468	  width: 24px; height: 24px;
469	  display: grid; place-items: center;
470	  color: var(--muted);
471	  border-radius: 3px;
472	}
473	.row-actions button:hover {
474	  background: var(--bg-2);
475	  color: var(--ink);
476	}
477	
478	.kebab-menu {
479	  position: absolute;
480	  top: calc(100% + 4px);
481	  right: 0;
482	  background: var(--surface);
483	  border: 1px solid var(--hairline-strong);
484	  border-radius: var(--radius-sm);
485	  padding: 3px;
486	  display: grid;
487	  min-width: 170px;
488	  z-index: 10;
489	  box-shadow: 0 4px 12px rgba(24,24,27,0.08);
490	}
491	.kebab-menu button {
492	  display: flex;
493	  align-items: center;
494	  gap: 8px;
495	  height: 26px;
496	  padding: 0 8px;
497	  font-size: 12px;
498	  text-align: left;
499	  color: var(--ink-2);
500	  width: 100%;
501	  border-radius: 2px;
502	}
503	.kebab-menu button:hover { background: var(--bg-2); color: var(--ink); }
504	.kebab-menu button.danger { color: var(--danger); }
505	.kebab-menu button.danger:hover { background: var(--danger-soft); color: var(--danger); }
506	.kebab-menu hr {
507	  border: none;
508	  border-top: 1px solid var(--hairline);
509	  margin: 3px 0;
510	}
511	.kebab-menu .shortcut {
512	  margin-left: auto;
513	  font-family: var(--font-mono);
514	  font-size: 10px;
515	  color: var(--muted);
516	}
517	
518	/* inline rename */
519	.row .name .title input {
520	  width: 100%;
521	  font-size: 13px;
522	  font-weight: 500;
523	  border: 1px solid var(--accent);
524	  border-radius: 2px;
525	  padding: 1px 4px;
526	  margin: -2px -5px;
527	  background: var(--surface);
528	}
529	
530	/* ——— Empty state ——— */
531	.empty {
532	  padding: 56px 24px 32px;
533	  text-align: center;
534	  background: var(--surface);
535	  border: 1px solid var(--hairline);
536	  border-top: none;
537	  border-radius: 0 0 var(--radius) var(--radius);
538	}
539	.empty h2 {
540	  font-weight: 600;
541	  font-size: 14px;
542	  margin: 0 0 4px;
543	  color: var(--ink);
544	}
545	.empty p {
546	  color: var(--muted);
547	  font-size: 12px;
548	  max-width: 360px;
549	  margin: 0 auto 16px;
550	}
551	
552	/* ——— Footer ——— */
553	.foot {
554	  margin-top: 32px;
555	  padding-top: 12px;
556	  border-top: 1px solid var(--hairline);
557	  display: flex;
558	  justify-content: space-between;
559	  font-size: 11px;
560	  color: var(--muted);
561	  font-family: var(--font-mono);
562	}
563	.foot a { color: var(--ink-2); text-decoration: none; }
564	.foot a:hover { color: var(--accent); }
565	
566	/* ——— View page ——— */
567	.view-shell {
568	  position: fixed;
569	  inset: 0;
570	  background: #0d0d0e;
571	  display: grid;
572	  place-items: center;
573	}
574	.view-iframe {
575	  width: 100%;
576	  height: 100%;
577	  border: 0;
578	  background: #fff;
579	}
580	
581	/* ——— Toast ——— */
582	.toast {
583	  position: fixed;
584	  bottom: 16px;
585	  left: 50%;
586	  transform: translateX(-50%);
587	  background: var(--ink);
588	  color: #fff;
589	  padding: 8px 12px;
590	  border-radius: var(--radius-sm);
591	  font-size: 12px;
592	  display: flex; align-items: center; gap: 8px;
593	  box-shadow: 0 4px 12px rgba(24,24,27,0.16);
594	  z-index: 50;
595	  animation: toastIn 140ms ease both;
596	}
597	.toast .check {
598	  width: 12px; height: 12px;
599	  border-radius: 50%;
600	  background: var(--success);
601	  display: grid; place-items: center;
602	  font-size: 8px;
603	  color: #fff;
604	}
605	@keyframes toastIn {
606	  from { opacity: 0; transform: translate(-50%, 4px); }
607	  to   { opacity: 1; transform: translate(-50%, 0); }
608	}
609	
610	/* ——— Animation helpers ——— */
611	.fade-in {
612	  animation: fadeIn 140ms ease both;
613	}
614	@keyframes fadeIn {
615	  from { opacity: 0; transform: translateY(-2px); }
616	  to   { opacity: 1; transform: translateY(0); }
617	}
618	
619	.share-panel-anim {
620	  display: grid;
621	  grid-template-rows: 0fr;
622	  transition: grid-template-rows 180ms ease;
623	}
624	.share-panel-anim.open { grid-template-rows: 1fr; }
625	.share-panel-anim > div { overflow: hidden; }
