file.content:
/* Rollout — utilitarian internal tool */
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');

:root {
  --bg: #FAFAFA;
  --bg-2: #F4F4F5;
  --surface: #FFFFFF;
  --ink: #18181B;
  --ink-2: #3F3F46;
  --muted: #71717A;
  --muted-2: #A1A1AA;
  --hairline: #E4E4E7;
  --hairline-strong: #D4D4D8;
  --accent: #2563EB;
  --accent-soft: #DBEAFE;
  --accent-ink: #1E40AF;
  --success: #16A34A;
  --success-soft: #DCFCE7;
  --danger: #DC2626;
  --danger-soft: #FEE2E2;
  --warn-soft: #FEF3C7;

  --font-sans: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, monospace;

  --radius: 4px;
  --radius-sm: 3px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0; padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 13px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button {
  font-family: inherit; font-size: inherit; color: inherit;
  background: none; border: none; padding: 0; cursor: pointer;
}
input, textarea {
  font-family: inherit; font-size: inherit; color: inherit;
  background: none; border: none; outline: none; padding: 0;
}

/* ——— App shell ——— */
.app {
  width: 100%;
  min-height: 100%;
  background: var(--bg);
}

.shell {
  max-width: 960px;
  margin: 0 auto;
  padding: 24px 32px 64px;
}

/* ——— Top bar ——— */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
  border-bottom: 1px solid var(--hairline);
  margin-bottom: 24px;
}
.wordmark {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.wordmark .logo {
  width: 18px; height: 18px;
  border-radius: 3px;
  background: var(--ink);
  color: #fff;
  display: grid; place-items: center;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
}
.wordmark .env {
  margin-left: 4px;
  font-size: 11px;
  color: var(--muted);
  font-weight: 400;
  padding: 2px 6px;
  border: 1px solid var(--hairline);
  border-radius: 2px;
}
.who {
  display: flex; align-items: center; gap: 10px;
  font-size: 12px; color: var(--ink-2);
}
.who .avatar {
  width: 22px; height: 22px;
  border-radius: 50%;
  background: var(--bg-2);
  color: var(--ink-2);
  font-size: 10px;
  font-weight: 600;
  display: grid; place-items: center;
  border: 1px solid var(--hairline);
}

/* ——— Page heading ——— */
.heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 0 16px;
}
.heading h1 {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 18px;
  line-height: 1.2;
  letter-spacing: -0.005em;
  margin: 0;
}
.heading .sub {
  color: var(--muted);
  font-size: 12px;
  margin-top: 2px;
}

/* ——— Buttons ——— */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 12px;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  transition: background 100ms ease;
}
.btn:hover { background: #000; border-color: #000; }
.btn:active { transform: translateY(0.5px); }

.btn-ghost {
  background: var(--surface);
  border: 1px solid var(--hairline-strong);
  color: var(--ink-2);
}
.btn-ghost:hover { background: var(--bg-2); color: var(--ink); }

.btn-accent {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}
.btn-accent:hover { background: var(--accent-ink); border-color: var(--accent-ink); }

.btn[disabled], .btn:disabled {
  opacity: 0.45; cursor: not-allowed;
}

.kbd {
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 1px 4px;
  border: 1px solid var(--hairline-strong);
  border-bottom-width: 2px;
  border-radius: 2px;
  color: var(--muted);
  background: var(--surface);
}

/* ——— Toolbar above list ——— */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-top: 1px solid var(--hairline);
  border-bottom: 1px solid var(--hairline);
}
.search {
  display: flex; align-items: center; gap: 8px;
  flex: 1;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--muted);
  font-size: 12px;
  max-width: 320px;
}
.search input {
  flex: 1;
  color: var(--ink);
  background: transparent;
}
.search input::placeholder { color: var(--muted-2); }
.toolbar .stats { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }

/* ——— Share panel (inline expanding) ——— */
.share-panel {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--radius);
  margin: 12px 0;
}
.share-panel-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid var(--hairline);
}
.share-panel-head .t {
  font-size: 12px; font-weight: 600; color: var(--ink);
  display: flex; align-items: center; gap: 8px;
}
.share-panel-head .t .badge {
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 1px 6px;
  background: var(--bg-2);
  border-radius: 2px;
  color: var(--muted);
  font-weight: 400;
}
.share-panel-head .x {
  width: 22px; height: 22px;
  display: grid; place-items: center;
  color: var(--muted);
  border-radius: 3px;
}
.share-panel-head .x:hover { background: var(--bg-2); color: var(--ink); }

.share-panel-inner {
  padding: 14px;
  display: grid;
  gap: 0;
}

.dropzone {
  border: 1px dashed var(--hairline-strong);
  border-radius: var(--radius-sm);
  padding: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--bg);
  transition: border-color 100ms ease, background 100ms ease;
  cursor: pointer;
}
.dropzone:hover { border-color: var(--accent); }
.dropzone.active {
  border-color: var(--accent);
  background: var(--accent-soft);
}
.dropzone .dz-left {
  display: flex; align-items: center; gap: 10px;
}
.dropzone .dz-icon {
  width: 28px; height: 32px;
  border: 1px solid var(--hairline-strong);
  border-radius: 2px;
  background: #fff;
  position: relative;
  flex-shrink: 0;
  display: grid; place-items: center;
  font-family: var(--font-mono);
  font-size: 8px;
  color: var(--muted);
  letter-spacing: 0;
}
.dropzone.has-file .dz-icon {
  border-color: var(--accent);
  color: var(--accent);
}
.dz-title { font-size: 12px; font-weight: 500; color: var(--ink); }
.dz-meta  { font-size: 11px; color: var(--muted); margin-top: 1px; font-variant-numeric: tabular-nums; }

.fields {
  display: grid;
  margin-top: 10px;
}
.field {
  display: grid;
  grid-template-columns: 84px 1fr;
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border: 1px solid var(--hairline);
  border-bottom: none;
}
.field:first-child { border-top-left-radius: var(--radius-sm); border-top-right-radius: var(--radius-sm); }
.field:last-child { border-bottom: 1px solid var(--hairline); border-bottom-left-radius: var(--radius-sm); border-bottom-right-radius: var(--radius-sm); }
.field label {
  font-size: 11px;
  color: var(--muted);
  font-weight: 500;
}
.field .input {
  font-family: var(--font-sans);
  font-size: 13px;
  color: var(--ink);
  width: 100%;
}
.field .input.mono { font-family: var(--font-mono); font-size: 12px; }
.field .input::placeholder { color: var(--muted-2); }

.field .preview {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--muted);
}
.field .preview .slug {
  color: var(--ink);
  background: var(--accent-soft);
  padding: 1px 4px;
  border-radius: 2px;
}

.share-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 12px;
}
.share-actions .hint { font-size: 11px; color: var(--muted); }
.share-actions .actions { display: flex; gap: 6px; }

/* ——— Success card ——— */
.success {
  display: grid;
  gap: 12px;
}
.success .ok {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px; color: var(--ink-2);
  padding: 8px 10px;
  background: var(--success-soft);
  border-radius: var(--radius-sm);
}
.success .ok .check {
  width: 14px; height: 14px;
  border-radius: 50%;
  background: var(--success);
  color: #fff;
  display: grid; place-items: center;
  font-size: 9px;
  flex-shrink: 0;
}
.url-pill {
  display: flex; align-items: stretch;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  overflow: hidden;
}
.url-pill .url {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--ink);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 7px 10px;
  background: var(--bg);
}
.url-pill .url .em { color: var(--accent); }
.url-pill button {
  height: auto;
  padding: 0 12px;
  background: var(--ink);
  color: #fff;
  font-size: 12px;
  font-weight: 500;
  display: inline-flex; align-items: center; gap: 6px;
  border-left: 1px solid var(--ink);
}
.url-pill button:hover { background: #000; }
.url-pill button.copied {
  background: var(--success);
}

/* ——— List ——— */
.list {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}
.list-head {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.2fr) 92px 70px 90px 36px;
  gap: 16px;
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 500;
  color: var(--muted);
  background: var(--bg-2);
  border-bottom: 1px solid var(--hairline);
}
.list-head > div {
  display: flex; align-items: center; gap: 4px;
}
.list-head .col-num { text-align: right; justify-content: flex-end; font-variant-numeric: tabular-nums; }

.row {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.2fr) 92px 70px 90px 36px;
  gap: 16px;
  align-items: center;
  padding: 9px 12px;
  border-bottom: 1px solid var(--hairline);
  position: relative;
  font-size: 13px;
}
.row:last-child { border-bottom: none; }
.row:hover { background: var(--bg); }

.row .name .title {
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.row .slug-col {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.row .col {
  font-size: 12px;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.row .col.muted { color: var(--muted); }
.row .col.num { text-align: right; }

.row-actions {
  display: flex;
  align-items: center;
  gap: 0;
  position: relative;
  justify-self: end;
}
.row-actions button {
  width: 24px; height: 24px;
  display: grid; place-items: center;
  color: var(--muted);
  border-radius: 3px;
}
.row-actions button:hover {
  background: var(--bg-2);
  color: var(--ink);
}

.kebab-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  background: var(--surface);
  border: 1px solid var(--hairline-strong);
  border-radius: var(--radius-sm);
  padding: 3px;
  display: grid;
  min-width: 170px;
  z-index: 10;
  box-shadow: 0 4px 12px rgba(24,24,27,0.08);
}
.kebab-menu button {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 26px;
  padding: 0 8px;
  font-size: 12px;
  text-align: left;
  color: var(--ink-2);
  width: 100%;
  border-radius: 2px;
}
.kebab-menu button:hover { background: var(--bg-2); color: var(--ink); }
.kebab-menu button.danger { color: var(--danger); }
.kebab-menu button.danger:hover { background: var(--danger-soft); color: var(--danger); }
.kebab-menu hr {
  border: none;
  border-top: 1px solid var(--hairline);
  margin: 3px 0;
}
.kebab-menu .shortcut {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--muted);
}

/* inline rename */
.row .name .title input {
  width: 100%;
  font-size: 13px;
  font-weight: 500;
  border: 1px solid var(--accent);
  border-radius: 2px;
  padding: 1px 4px;
  margin: -2px -5px;
  background: var(--surface);
}

/* ——— Empty state ——— */
.empty {
  padding: 56px 24px 32px;
  text-align: center;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}
.empty h2 {
  font-weight: 600;
  font-size: 14px;
  margin: 0 0 4px;
  color: var(--ink);
}
.empty p {
  color: var(--muted);
  font-size: 12px;
  max-width: 360px;
  margin: 0 auto 16px;
}

/* ——— Footer ——— */
.foot {
  margin-top: 32px;
  padding-top: 12px;
  border-top: 1px solid var(--hairline);
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--muted);
  font-family: var(--font-mono);
}
.foot a { color: var(--ink-2); text-decoration: none; }
.foot a:hover { color: var(--accent); }

/* ——— View page ——— */
.view-shell {
  position: fixed;
  inset: 0;
  background: #0d0d0e;
  display: grid;
  place-items: center;
}
.view-iframe {
  width: 100%;
  height: 100%;
  border: 0;
  background: #fff;
}

/* ——— Toast ——— */
.toast {
  position: fixed;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  display: flex; align-items: center; gap: 8px;
  box-shadow: 0 4px 12px rgba(24,24,27,0.16);
  z-index: 50;
  animation: toastIn 140ms ease both;
}
.toast .check {
  width: 12px; height: 12px;
  border-radius: 50%;
  background: var(--success);
  display: grid; place-items: center;
  font-size: 8px;
  color: #fff;
}
@keyframes toastIn {
  from { opacity: 0; transform: translate(-50%, 4px); }
  to   { opacity: 1; transform: translate(-50%, 0); }
}

/* ——— Animation helpers ——— */
.fade-in {
  animation: fadeIn 140ms ease both;
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-2px); }
  to   { opacity: 1; transform: translateY(0); }
}

.share-panel-anim {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 180ms ease;
}
.share-panel-anim.open { grid-template-rows: 1fr; }
.share-panel-anim > div { overflow: hidden; }

// Mock presentation data
