189	function PresentationRow({ p, user, onRename, onDelete, onToast }) {
190	  const [menuOpen, setMenuOpen] = React.useState(false);
191	  const [editing, setEditing] = React.useState(false);
192	  const [draft, setDraft] = React.useState(p.title);
193	  const menuRef = React.useRef(null);
194	
195	  React.useEffect(() => {
196	    if (!menuOpen) return;
