281	  const [query, setQuery] = React.useState('');
282	
283	  function showToast(msg) {
284	    setToast(msg);
285	    clearTimeout(showToast._t);
286	    showToast._t = setTimeout(() => setToast(null), 1800);
287	  }
288	  function onShared(p) { setItems(prev => [p, ...prev]); }
