309	
310	        <SharePanel
311	          user={user}
312	          open={sharing}
313	          onClose={() => setSharing(false)}
314	          onShared={onShared}
315	        />
316	
317	        <Toolbar count={filtered.length} query={query} setQuery={setQuery} />
318	
319	        <div className="list">
320	          <div className="list-head">
321	            <div>Name</div>
322	            <div>URL</div>
323	            <div>Shared</div>
324	            <div className="col-num">Views</div>
325	            <div>Last viewed</div>
326	            <div></div>
327	          </div>
328	          {filtered.map(p => (
329	            <PresentationRow
330	              key={p.id}
331	              p={p}
332	              user={user}
333	              onRename={onRename}
334	              onDelete={onDelete}
335	              onToast={showToast}
336	            />
337	          ))}
338	        </div>
339	
340	        <footer className="foot">
341	          <span>rollout v0.4.2 · sso · {user.email}</span>
342	          <span><a href="#">docs</a> · <a href="#">api</a> · <a href="#">help</a></span>
343	        </footer>
344	      </div>
345	
346	      {toast && (
347	        <div className="toast">
348	          <span className="check">✓</span>
349	          {toast}
350	        </div>
351	      )}
352	    </div>
353	  );
354	}
355	
356	window.Dashboard = Dashboard;
357	window.SharePanel = SharePanel;
358	window.TopBar = TopBar;
359	window.Heading = Heading;
360	window.Toolbar = Toolbar;
361	window.PresentationRow = PresentationRow;
