// Dashboard — utilitarian internal tool

function TopBar({ user }) {
  return (
    <header className="topbar">
      <div className="wordmark">
        <span className="logo">R</span>
        rollout
        <span className="env">internal</span>
      </div>
      <div className="who">
        <span>{user.email}</span>
        <span className="avatar">{user.initials}</span>
      </div>
    </header>
  );
}

function Heading({ onShare, sharing, count }) {
  return (
    <div className="heading">
      <div>
        <h1>Presentations</h1>
        <div className="sub">{count} shared · /{window.CURRENT_USER.id}</div>
      </div>
      {!sharing && (
        <button className="btn" onClick={onShare}>
          Share new <span className="kbd" style={{ color: 'rgba(255,255,255,0.7)', borderColor: 'rgba(255,255,255,0.3)', background: 'transparent' }}>N</span>
        </button>
      )}
    </div>
  );
}

function SharePanel({ user, open, onClose, onShared }) {
  const [file, setFile] = React.useState(null);
  const [name, setName] = React.useState('');
  const [dragging, setDragging] = React.useState(false);
  const [sharedUrl, setSharedUrl] = React.useState(null);
  const [copied, setCopied] = React.useState(false);
  const inputRef = React.useRef(null);

  React.useEffect(() => {
    if (open) {
      setFile(null); setName(''); setSharedUrl(null); setCopied(false);
    }
  }, [open]);

  const slug = slugify(name || (file ? file.name.replace(/\.html?$/i, '') : ''));
  const ready = file && slug.length > 0;

  function pickFile(f) {
    if (!f) return;
    setFile({ name: f.name, size: f.size });
    if (!name) setName(f.name.replace(/\.html?$/i, '').replace(/[-_]+/g, ' '));
  }
  function onDrop(e) {
    e.preventDefault(); setDragging(false);
    const f = e.dataTransfer.files[0];
    if (f) pickFile(f);
  }
  function onShare() {
    const url = `rollout.company.com/${user.id}/${slug}`;
    setSharedUrl(url);
    try { navigator.clipboard?.writeText('https://' + url); } catch (e) {}
    setCopied(true);
    onShared && onShared({
      id: 'new-' + Date.now(),
      title: name || file.name.replace(/\.html?$/i, ''),
      slug, uploaded: 'just now', lastViewed: '—', views: 0,
      size: file.size,
    });
  }
  function copyAgain() {
    try { navigator.clipboard?.writeText('https://' + sharedUrl); } catch (e) {}
    setCopied(true);
    setTimeout(() => setCopied(false), 1400);
  }

  return (
    <div className={'share-panel-anim' + (open ? ' open' : '')}>
      <div>
        <div className="share-panel">
          <div className="share-panel-head">
            <div className="t">
              {sharedUrl ? 'Shared' : 'Share new presentation'}
              {!sharedUrl && <span className="badge">POST /presentations</span>}
            </div>
            <button className="x" onClick={onClose}><Icon.X /></button>
          </div>
          <div className="share-panel-inner">
            {!sharedUrl && (
              <>
                <div
                  className={'dropzone' + (dragging ? ' active' : '') + (file ? ' has-file' : '')}
                  onClick={() => inputRef.current?.click()}
                  onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
                  onDragLeave={() => setDragging(false)}
                  onDrop={onDrop}
                >
                  <div className="dz-left">
                    <div className="dz-icon">html</div>
                    <div>
                      <div className="dz-title">
                        {file ? file.name : 'Drop .html file or click to browse'}
                      </div>
                      <div className="dz-meta">
                        {file ? formatBytes(file.size) + ' · ready to upload' : 'single self-contained file'}
                      </div>
                    </div>
                  </div>
                  {file && (
                    <button
                      className="btn-ghost"
                      style={{ height: 24, padding: '0 8px', borderRadius: 3, fontSize: 11 }}
                      onClick={(e) => { e.stopPropagation(); setFile(null); }}
                    >
                      Remove
                    </button>
                  )}
                  <input
                    ref={inputRef}
                    type="file"
                    accept=".html,.htm"
                    style={{ display: 'none' }}
                    onChange={(e) => pickFile(e.target.files[0])}
                  />
                </div>

                <div className="fields">
                  <div className="field">
                    <label htmlFor="name">Name</label>
                    <input
                      id="name"
                      className="input"
                      placeholder="give it a name"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                    />
                  </div>
                  <div className="field">
                    <label>URL</label>
                    <div className="preview">
                      rollout.company.com/{user.id}/<span className="slug">{slug || 'slug'}</span>
                    </div>
                  </div>
                </div>

                <div className="share-actions">
                  <div className="hint">URL will be copied to your clipboard.</div>
                  <div className="actions">
                    <button className="btn btn-ghost" onClick={onClose}>Cancel</button>
                    <button className="btn btn-accent" disabled={!ready} onClick={onShare}>Share</button>
                  </div>
                </div>
              </>
            )}

            {sharedUrl && (
              <div className="success fade-in">
                <div className="ok">
                  <span className="check">✓</span>
                  <span>Presentation shared. URL copied to clipboard.</span>
                </div>
                <div className="url-pill">
                  <span className="url">
                    https://<span className="em">{sharedUrl}</span>
                  </span>
                  <button className={copied ? 'copied' : ''} onClick={copyAgain}>
                    <Icon.Copy />
                    {copied ? 'copied' : 'copy'}
                  </button>
                </div>
                <div className="share-actions">
                  <div className="hint">Anyone at the company with the link can view.</div>
                  <div className="actions">
                    <button className="btn btn-ghost" onClick={onClose}>Done</button>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function PresentationRow({ p, user, onRename, onDelete, onToast }) {
  const [menuOpen, setMenuOpen] = React.useState(false);
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(p.title);
  const menuRef = React.useRef(null);

  React.useEffect(() => {
    if (!menuOpen) return;
    const onDoc = (e) => { if (!menuRef.current?.contains(e.target)) setMenuOpen(false); };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, [menuOpen]);

  function copyUrl() {
    const url = `https://rollout.company.com/${user.id}/${p.slug}`;
    try { navigator.clipboard?.writeText(url); } catch (e) {}
    onToast('Link copied');
  }
  function commitRename() {
    if (draft.trim() && draft !== p.title) onRename(p.id, draft.trim());
    setEditing(false);
  }

  return (
    <div className="row">
      <div className="name">
        <div className="title">
          {editing ? (
            <input
              autoFocus
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onBlur={commitRename}
              onKeyDown={(e) => {
                if (e.key === 'Enter') commitRename();
                if (e.key === 'Escape') { setDraft(p.title); setEditing(false); }
              }}
            />
          ) : p.title}
        </div>
      </div>
      <div className="slug-col">/{user.id}/{p.slug}</div>
      <div className="col muted">{p.uploaded}</div>
      <div className="col num">{p.views.toLocaleString()}</div>
      <div className="col muted">{p.lastViewed}</div>

      <div className="row-actions" ref={menuRef}>
        <button title="Copy link" onClick={copyUrl}><Icon.Copy /></button>
        <button title="Open" onClick={() => onToast('Opening preview…')}><Icon.Open /></button>
        <button title="More" onClick={() => setMenuOpen(o => !o)}><Icon.More /></button>

        {menuOpen && (
          <div className="kebab-menu fade-in">
            <button onClick={() => { setMenuOpen(false); setEditing(true); }}>
              <Icon.Edit /> Rename
              <span className="shortcut">R</span>
            </button>
            <button onClick={() => { setMenuOpen(false); onToast('Choose a new file…'); }}>
              <Icon.Replace /> Replace file
            </button>
            <hr />
            <button className="danger" onClick={() => { setMenuOpen(false); onDelete(p.id); }}>
              <Icon.Trash /> Delete
              <span className="shortcut" style={{ color: 'inherit', opacity: 0.6 }}>⌫</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function Toolbar({ count, query, setQuery }) {
  return (
    <div className="toolbar">
      <div className="search">
        <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
          <circle cx="7" cy="7" r="4.5"/>
          <path d="M10.5 10.5L13.5 13.5" strokeLinecap="round"/>
        </svg>
        <input placeholder="Filter presentations…" value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>
      <div className="stats">{count} {count === 1 ? 'presentation' : 'presentations'}</div>
    </div>
  );
}

function Dashboard() {
  const [user] = React.useState(window.CURRENT_USER);
  const [items, setItems] = React.useState(window.MOCK_PRESENTATIONS);
  const [sharing, setSharing] = React.useState(false);
  const [toast, setToast] = React.useState(null);
  const [query, setQuery] = React.useState('');

  function showToast(msg) {
    setToast(msg);
    clearTimeout(showToast._t);
    showToast._t = setTimeout(() => setToast(null), 1800);
  }
  function onShared(p) { setItems(prev => [p, ...prev]); }
  function onRename(id, title) {
    setItems(prev => prev.map(p => p.id === id ? { ...p, title } : p));
    showToast('Renamed');
  }
  function onDelete(id) {
    setItems(prev => prev.filter(p => p.id !== id));
    showToast('Deleted');
  }

  const filtered = items.filter(p => {
    if (!query) return true;
    const q = query.toLowerCase();
    return p.title.toLowerCase().includes(q) || p.slug.toLowerCase().includes(q);
  });

  return (
    <div className="app">
      <div className="shell">
        <TopBar user={user} />
        <Heading onShare={() => setSharing(true)} sharing={sharing} count={items.length} />

        <SharePanel
          user={user}
          open={sharing}
          onClose={() => setSharing(false)}
          onShared={onShared}
        />

        <Toolbar count={filtered.length} query={query} setQuery={setQuery} />

        <div className="list">
          <div className="list-head">
            <div>Name</div>
            <div>URL</div>
            <div>Shared</div>
            <div className="col-num">Views</div>
            <div>Last viewed</div>
            <div></div>
          </div>
          {filtered.map(p => (
            <PresentationRow
              key={p.id}
              p={p}
              user={user}
              onRename={onRename}
              onDelete={onDelete}
              onToast={showToast}
            />
          ))}
        </div>

        <footer className="foot">
          <span>rollout v0.4.2 · sso · {user.email}</span>
          <span><a href="#">docs</a> · <a href="#">api</a> · <a href="#">help</a></span>
        </footer>
      </div>

      {toast && (
        <div className="toast">
          <span className="check">✓</span>
          {toast}
        </div>
      )}
    </div>
  );
}

